        }
        if (n.is("call")) {
            if (r.function(n.name)) |fi| { if (n.args.len > r.functions.items[fi].node.params.len) r.staticError(n.token.position, 4, try std.fmt.allocPrint(r.a, "too many arguments to {s}", .{n.name})); }
